const ignoreSegments = ["node_modules", ".git", "formatter-common-config", "dist", "bin", "obj"];
const timers = new Map();
const DEBOUNCE_MS = 150;

const shouldIgnore = (filename) => ignoreSegments.some((seg) => filename.split(/[\\/]/).includes(seg));

